/// Huffman token decoding (`VP6_DecodeBlock` 0x8029a898 / `VP6_ExtractTokenN`): tokens 0 (zero run), 1-10 (values,
/// extra bits), 11 (end of block); zero-DC and first-AC end-of-block runs are counted per plane type.
fn parse_coeff_huffman(&mut self,bits:&mut Bits)->Result<(),String>{
    for b in 0..6{
        let pt=(b>3) as usize;let mut ct=0usize;let mut idx=0usize;
        let mut hsel=usize::MAX;
        loop{
            let mut run=1usize;
            if idx<2&&self.nb_null[idx][pt]>0{
                self.nb_null[idx][pt]-=1;
                if idx>0{break}
            }else{
                let tok=if hsel==usize::MAX{self.dccv_h[pt].read(bits)?}else{self.ract_h[hsel].read(bits)?};
                if tok==0{
                    if idx>0{
                        run+=self.runv_h[(idx>=6) as usize].read(bits)? as usize;
                        if run>=9{run+=bits.get(6)? as usize}
                    }else{self.nb_null[0][pt]=Self::nb_null_count(bits)?}
                    ct=0;
                }else if tok==11{
                    if idx==1{self.nb_null[1][pt]=Self::nb_null_count(bits)?}
                    break;
                }else{
                    let mut v=t::TOKEN_MIN[tok as usize];
                    if tok>4{v+=bits.get(if tok<=9{tok as u32-4}else{11})? as i32}
                    ct=1+(v>1) as usize;
                    if bits.bit()?==1{v=-v}
                    if idx!=0{v*=self.dequant_ac}
                    let pos=self.model.index_to_pos[idx] as usize;self.coeff[b][t::ZIGZAG_T[pos] as usize]=v;
                }
            }
            idx+=run;
            if idx>=64{break}
            let g=t::HUFF_BANDS[idx] as usize;
            hsel=pt*18+ct*6+g;
        }
        self.selector[b]=self.model.selector[idx.min(63)] as usize;
    }
    Ok(())
}
